-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.monk.brewmaster.Name"] = "推薦"
L["rm.mop.monk.brewmaster.Description"] = "在釀酒專精下自動選用。以滅寂腿維持醉拳，真氣足夠容納時就使用酒罈破，受傷時使用斗轉星移（低於 35% 時立即使用），以刺擊消耗能量，使用虎掌以獲得虎威並作為免費填充（34 級前以刺擊累積真氣），可用時使用幽冥掌。戰鬥外從遠處：真氣波、微醺酒氣、天引躍擊或酒罈破。三個以上敵人時：飛玉疾風、火焰吐息，以及只在醉拳還有剩餘時間時使用鶴旋踢。提醒：磐牛式、御傳心法、醉仙大緩勁時使用清心絕釀（已累積醉拳時則在醉仙中緩勁時使用）、六層起使用飄渺絕釀、有提氣凝勁時使用護身氣勁、真氣絕釀、雪怒、石形絕釀、生命力低時使用卸勁訣或祛魔訣、天矛鎖喉手。玄牛雕像的提醒預設關閉；移傷氣勁、冥思禪功與嘲心嘯由你自行處理。"
L["rm.mop.monk.brewmaster.offensive.Name"] = "傷害優先（模擬器）"
L["rm.mop.monk.brewmaster.offensive.Description"] = "釀酒內建循環的替代方案，預設關閉：啟用它並停用釀酒內建循環，或提高它的優先順序。依照模擬器為裝備遠超內容的坦克提供的傷害優先清單：酒罈破之前使用飛玉疾風，真氣用於滅寂腿以造成傷害，不例行使用清心絕釀或護身氣勁（清心絕釀只在 T15 淨化者觸發時亮起）。飄渺絕釀、真氣絕釀、雪怒與石形絕釀仍會提醒。"
L["rm.mop.monk.mistweaver.Name"] = "推薦"
L["rm.mop.monk.mistweaver.Description"] = "在織霧專精下自動選用。有友方目標時治療該目標：回生迷霧冷卻結束即使用，附近有三名以上盟友受傷時使用振氣訣，以斗轉星移與你的真氣天賦獲得真氣，隊伍受傷時使用飛玉疾風或鶴旋踢，五層精活迷霧時使用回春迷霧，目標低於 80% 時使用舒和之霧，然後在該引導中使用迷霧繚繞與回春迷霧。有敵方目標時改以拳腳攻擊進行治療（拳織）：以虎掌與肌肉記憶觸發時的滅寂腿維持虎威與蛟龍之誠，真氣全滿時使用滅寂腿，五層精活迷霧時使用回春迷霧，以回生迷霧與斗轉星移獲得真氣，刺擊。提醒：靈蛟式、御傳心法、隊伍中的玉蛟雕像、空閒時使用法力茶、聚雷茶、真氣絕釀、對低於 35% 的友方使用氣繭護體、雪怒、化毒袪病、防禦技能、天矛鎖喉手。要治療誰由你選擇；五氣歸元（提醒預設關閉）與治療玉由你自行處理。"
L["rm.mop.monk.unspecialized.Name"] = "選擇專精前"
L["rm.mop.monk.unspecialized.Description"] = "適用於 1 至 9 級，或尚未選擇專精的任何武僧；選擇專精後由專精內建循環接手。維持猛虎式與虎威，將兩點真氣用於滅寂腿，受傷時使用斗轉星移，否則使用刺擊。"
L["rm.mop.monk.windwalker.Name"] = "推薦"
L["rm.mop.monk.windwalker.Description"] = "在御風專精下自動選用。可用時使用幽冥掌，以虎掌維持虎威，翔陽腳冷卻結束即使用，真氣波，連段破觸發，你站著不動且引導不會使能量溢出時使用狂拳連打，缺少兩點真氣時使用刺擊（受傷時改用斗轉星移），在不影響下一次翔陽腳的前提下使用滅寂腿。兩個以上敵人時以翔陽腳維持其減益效果，三個起加入鶴旋踢或飛玉疾風。提醒：猛虎式、御傳心法與雪怒心法、19 層時使用虎眼絕釀（有真氣可消耗時為 15 層，嗜血術期間或戰鬥接近尾聲時為 10 層）、能量低時使用凝神絕釀、真氣絕釀、雪怒、兩個敵人時使用風、火、大地（對第二個敵人施放）、乾坤挪移、防禦技能與天矛鎖喉手。能量溢出檢查使用的是能量門檻，請依你的加速調整。"
L["rm.mop.monk.windwalker.simc.Name"] = "SimulationCraft 5.4.8（Hekili 與 MaxDps）"
L["rm.mop.monk.windwalker.simc.Description"] = "御風內建循環的替代方案，預設關閉：啟用它並停用御風內建循環，或提高它的優先順序。Hekili 與 MaxDps 插件所附的原始 SimulationCraft 清單：虎威在剩三秒時刷新，翔陽腳的減益效果不在時優先使用翔陽腳，狂拳連打保留給虎眼絕釀（生效中或 15 層），20 層時或 15 層且有真氣並兩個增益效果都生效時使用虎眼絕釀。三個以上敵人時以鶴旋踢消耗，只在真氣全滿時使用翔陽腳，並在能量低於 60 時蓄積能量。"
L["rm.retail.monk.brewmaster.Name"] = "暴雪戰鬥助手，含絕釀技能"
L["rm.retail.monk.brewmaster.Description"] = "推薦釀酒專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。戰鬥助手不會使用任何絕釀技能，因此依照 Icy Veins 的建議，絕釀技能以提醒的形式顯示在它旁邊：玄牛絕釀、召喚玄牛怒兆、清心絕釀、天尊絕釀或星界灌注以及幽冥掌會在戰鬥中一旦就緒就亮起（Rotation Master 目前還無法讀取醉仙緩勁，因此醉仙緩勁有多重仍由你判斷）。另外還有對可中斷的施法使用天矛鎖喉手，以及戰鬥中只要就緒就使用石形絕釀與你的種族冷卻技能；敵人的施法在戰鬥中會被隱藏，因此中斷提醒只會在遊戲顯示它們的場合亮起，而且正式版中生命力是隱藏的，因此何時使用石形絕釀由你決定。"
L["rm.retail.monk.brewmaster.guide.Name"] = "參考（Icy Veins）"
L["rm.retail.monk.brewmaster.guide.Description"] = "僅供參考，預設關閉：Icy Veins 的釀酒優先順序（SimulationCraft 的思路大致相同）。滅寂連打、空酒桶與充能在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作。以酒罈破拉怪。滅寂腿；真氣爆裂（和諧大師）；滅寂連打觸發時使用虎掌；充能已滿或有空酒桶時使用酒罈破；火焰吐息；在爆炸酒桶之前使用飛玉疾風；真氣爆裂（影潘）；酒罈破；三個以上敵人時使用飛玉疾風與鶴旋踢；虎掌；斗轉星移。提醒：清心絕釀與天尊絕釀都用完後使用玄牛絕釀、召喚玄牛怒兆、清心絕釀、天尊絕釀或星界灌注、幽冥掌以及功能性提醒。"
L["rm.retail.monk.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.monk.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是武僧的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個武僧內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.monk.mistweaver.Name"] = "參考（Icy Veins）"
L["rm.retail.monk.mistweaver.Description"] = "僅供參考，預設關閉。暴雪沒有為治療者提供戰鬥助手清單，而且在至暗之夜的戰鬥中，盟友的生命力、回生迷霧的充能、法力茶的層數與觸發效果都對插件隱藏，因此無法給出治療建議；請自行選擇治療技能。對敵對目標時，它會建議拳療的填充技能：翔陽腳、滅寂腿與虎掌；對友方目標或沒有目標時不建議任何技能。提醒：天矛鎖喉手，以及戰鬥中只要就緒就使用石形絕釀與你的種族冷卻技能。"
L["rm.retail.monk.windwalker.Name"] = "暴雪戰鬥助手"
L["rm.retail.monk.windwalker.Description"] = "推薦御風專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議（它本身就會維持精通：連環打）；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的登峰造極、天尊導體、召喚白虎雪怒與乾坤挪移、對可中斷的施法使用天矛鎖喉手，以及戰鬥中只要就緒就使用石形絕釀與你的種族冷卻技能。敵人的施法在戰鬥中會被隱藏，因此中斷提醒只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用石形絕釀由你決定。"
L["rm.retail.monk.windwalker.guide.Name"] = "參考（Icy Veins 與 SimulationCraft）"
L["rm.retail.monk.windwalker.guide.Description"] = "僅供參考，預設關閉：Icy Veins 的天尊引導者優先順序。每一步都會維持精通：連環打（從不重複上一個施放的法術）；真氣與你自己的施法仍可讀取，但玉蛟之心、登峰造極、滅寂腿！與赤吉之舞在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作；正式版中能量是隱藏的，因此能量溢出前的虎掌未納入。召喚白虎雪怒還有 10 秒以上才就緒時使用迴龍升天破；真氣不足或登峰造極即將結束時使用蒼穹踐踏；沒有玉蛟之心時使用天尊導體；玉蛟之心即將結束時使用狂拳連打；天尊導體、召喚白虎雪怒、狂拳連打、迴龍升天破、馭風打擊；真氣不夠施放狂拳連打時使用滅寂腿；疾風踢、翔陽腳；有兩層滅寂腿！充能或在登峰造極期間使用滅寂腿；登峰造極期間或赤吉之舞觸發時使用鶴旋踢；幽冥掌；虎掌、滅寂腿、風刃斬作為填充。提醒：乾坤挪移以及功能性提醒。"
